arguments.command:
powershell -Command "
$result = @{}
try {
    $wsusPath = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\Results\Install'
    if (Test-Path $wsusPath) {
        $lastSuccess = (Get-ItemProperty $wsusPath).LastSuccessTime
        $result.WindowsUpdateLastSuccess = $lastSuccess.ToString()
    } else {
        $result.WindowsUpdateLastSuccess = 'Unable to read registry key'
    }
} catch {
    $result.WindowsUpdateLastSuccess = 'Error: ' + $_.Exception.Message
}

try {
    $sshService = Get-Service -Name sshd -ErrorAction SilentlyContinue
    if ($sshService) {
        $result.SSHServiceStatus = $sshService.Status.ToString()
    } else {
        $result.SSHServiceStatus = 'Service not found'
    }
} catch {
    $result.SSHServiceStatus = 'Error: ' + $_.Exception.Message
}

try {
    $blOutput = manage-bde -status C: 2>&1
    if ($blOutput -match 'Protection Status:\s+(.+)') {
        $result.BitLockerProtectionStatus = $Matches[1].Trim()
    } else {
        $result.BitLockerProtectionStatus = 'Unable to parse: ' + $blOutput
    }
} catch {
    $result.BitLockerProtectionStatus = 'Error: ' + $_.Exception.Message
}

$result | ConvertTo-Json -Depth 3
"

